import React from 'react';
import { Zap, Leaf, TrendingUp, BarChart } from 'lucide-react';

const EnergyGaugeRing = ({ percentage = 80, color = '#059669', size = 56, strokeWidth = 5.5, label }) => {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div style={{ position: 'relative', width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
      <svg width={size} height={size} style={{ transform: 'rotate(-90deg)' }}>
        <circle cx={size / 2} cy={size / 2} r={radius} stroke="#E2E8F0" strokeWidth={strokeWidth} fill="transparent" />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke={color}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          fill="transparent"
        />
      </svg>
      <span style={{ position: 'absolute', fontSize: '0.68rem', fontWeight: '900', color: '#0F172A' }}>
        {label || `${Math.round(percentage)}%`}
      </span>
    </div>
  );
};

const EnergyDashboardCard = () => {
  return (
    <div className="glass-card" style={{ padding: '1.5rem', marginBottom: '1.75rem', background: '#ffffff', borderRadius: '14px', border: '1px solid #E2E8F0' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
        <div>
          <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Zap size={20} style={{ color: 'var(--accent-primary)' }} /> Plant Energy & Sustainability Analytics
          </h3>
          <p style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: '600', marginTop: '2px' }}>
            Power Usage, Peak Demand Hours, and Carbon Footprint Tracking
          </p>
        </div>
        <span className="badge badge-running" style={{ fontWeight: '800' }}>Eco Rating: Grade A+</span>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(210px, 1fr))', gap: '1.1rem' }}>
        {/* TODAY'S ENERGY */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>TODAY'S ENERGY</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#0F172A', marginTop: '2px' }}>1,245 <span style={{ fontSize: '0.78rem' }}>kWh</span></div>
            <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '3px', fontWeight: '800' }}>-3.2% vs Yesterday</div>
          </div>
          <EnergyGaugeRing percentage={72} color="#059669" />
        </div>

        {/* WEEKLY ENERGY */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>WEEKLY ENERGY</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#0F172A', marginTop: '2px' }}>8,715 <span style={{ fontSize: '0.78rem' }}>kWh</span></div>
            <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '3px', fontWeight: '800' }}>Within Budget</div>
          </div>
          <EnergyGaugeRing percentage={85} color="#2563EB" />
        </div>

        {/* PEAK LOAD */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>PEAK LOAD</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#2563EB', marginTop: '2px' }}>18.5 <span style={{ fontSize: '0.78rem' }}>kW</span></div>
            <div style={{ fontSize: '0.72rem', color: '#64748B', marginTop: '3px', fontWeight: '700' }}>Logged at 14:30 PM</div>
          </div>
          <EnergyGaugeRing percentage={92.5} color="#2563EB" label="18.5" />
        </div>

        {/* AVG CONSUMPTION */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>AVG CONSUMPTION</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#0F172A', marginTop: '2px' }}>14.2 <span style={{ fontSize: '0.78rem' }}>kW</span></div>
            <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '3px', fontWeight: '800' }}>Optimal Baseload</div>
          </div>
          <EnergyGaugeRing percentage={71} color="#059669" label="14.2" />
        </div>

        {/* CARBON FOOTPRINT */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>CARBON FOOTPRINT</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#059669', marginTop: '2px' }}>0.28 <span style={{ fontSize: '0.78rem' }}>kg CO₂/m</span></div>
            <div style={{ fontSize: '0.72rem', color: '#059669', marginTop: '3px', fontWeight: '800' }}>Zero Direct Carbon</div>
          </div>
          <EnergyGaugeRing percentage={98} color="#059669" label="A+" />
        </div>
      </div>
    </div>
  );
};

export default EnergyDashboardCard;
